#![forbid(unsafe_code)]

//! Replays `tests/fixtures/golden_vectors.json` (in this repo, generated by
//! the Python reference model under `tools/staking_rewards_model.py`) byte-
//! for-byte against `core`, asserting every step's accepted/rejected result
//! and the exact after-state bytes.
//!
//! No JSON crate dependency (core/ and its tests stay dependency-free, and
//! this avoids any question about fetching a new crate offline): a minimal
//! purpose-built parser below handles exactly this file's shape.

use avm_staking_rewards_core::State;
use std::fs;

// ---- minimal JSON parser, just enough for this file's shape ----

#[derive(Debug, Clone)]
enum Json {
    Null,
    Bool(bool),
    Num(f64),
    Str(String),
    Arr(Vec<Json>),
    Obj(Vec<(String, Json)>),
}

struct Parser<'a> {
    s: &'a [u8],
    pos: usize,
}

impl<'a> Parser<'a> {
    fn new(s: &'a str) -> Self {
        Self { s: s.as_bytes(), pos: 0 }
    }

    fn skip_ws(&mut self) {
        while self.pos < self.s.len() && (self.s[self.pos] as char).is_whitespace() {
            self.pos += 1;
        }
    }

    fn peek(&self) -> u8 {
        self.s[self.pos]
    }

    fn parse_value(&mut self) -> Json {
        self.skip_ws();
        match self.peek() {
            b'{' => self.parse_obj(),
            b'[' => self.parse_arr(),
            b'"' => Json::Str(self.parse_str()),
            b't' => {
                self.pos += 4;
                Json::Bool(true)
            }
            b'f' => {
                self.pos += 5;
                Json::Bool(false)
            }
            b'n' => {
                self.pos += 4;
                Json::Null
            }
            _ => self.parse_num(),
        }
    }

    fn parse_obj(&mut self) -> Json {
        self.pos += 1; // '{'
        let mut out = Vec::new();
        self.skip_ws();
        if self.peek() == b'}' {
            self.pos += 1;
            return Json::Obj(out);
        }
        loop {
            self.skip_ws();
            let key = self.parse_str();
            self.skip_ws();
            self.pos += 1; // ':'
            let val = self.parse_value();
            out.push((key, val));
            self.skip_ws();
            match self.peek() {
                b',' => {
                    self.pos += 1;
                }
                b'}' => {
                    self.pos += 1;
                    break;
                }
                _ => panic!("bad json object"),
            }
        }
        Json::Obj(out)
    }

    fn parse_arr(&mut self) -> Json {
        self.pos += 1; // '['
        let mut out = Vec::new();
        self.skip_ws();
        if self.peek() == b']' {
            self.pos += 1;
            return Json::Arr(out);
        }
        loop {
            let val = self.parse_value();
            out.push(val);
            self.skip_ws();
            match self.peek() {
                b',' => {
                    self.pos += 1;
                }
                b']' => {
                    self.pos += 1;
                    break;
                }
                _ => panic!("bad json array"),
            }
        }
        Json::Arr(out)
    }

    fn parse_str(&mut self) -> String {
        self.pos += 1; // opening quote
        let mut out = String::new();
        loop {
            let c = self.peek();
            if c == b'"' {
                self.pos += 1;
                break;
            }
            if c == b'\\' {
                self.pos += 1;
                let esc = self.peek();
                match esc {
                    b'n' => out.push('\n'),
                    b't' => out.push('\t'),
                    b'"' => out.push('"'),
                    b'\\' => out.push('\\'),
                    _ => out.push(esc as char),
                }
                self.pos += 1;
            } else {
                out.push(c as char);
                self.pos += 1;
            }
        }
        out
    }

    fn parse_num(&mut self) -> Json {
        let start = self.pos;
        while self.pos < self.s.len()
            && matches!(self.peek(), b'0'..=b'9' | b'-' | b'+' | b'.' | b'e' | b'E')
        {
            self.pos += 1;
        }
        let text = std::str::from_utf8(&self.s[start..self.pos]).unwrap();
        Json::Num(text.parse().unwrap())
    }
}

fn parse_json(text: &str) -> Json {
    let mut p = Parser::new(text);
    p.parse_value()
}

fn as_obj(j: &Json) -> &[(String, Json)] {
    match j {
        Json::Obj(o) => o,
        _ => panic!("expected object"),
    }
}
fn as_arr(j: &Json) -> &[Json] {
    match j {
        Json::Arr(a) => a,
        _ => panic!("expected array"),
    }
}
fn as_str(j: &Json) -> &str {
    match j {
        Json::Str(s) => s,
        _ => panic!("expected string"),
    }
}
fn as_bool(j: &Json) -> bool {
    match j {
        Json::Bool(b) => *b,
        _ => panic!("expected bool"),
    }
}
fn as_num(j: &Json) -> u128 {
    match j {
        Json::Num(n) => *n as u128,
        Json::Str(s) => s.parse().unwrap(),
        _ => panic!("expected number"),
    }
}
fn get<'a>(obj: &'a [(String, Json)], key: &str) -> &'a Json {
    obj.iter().find(|(k, _)| k == key).map(|(_, v)| v).unwrap_or(&Json::Null)
}

fn account_bytes(s: &str) -> [u8; 32] {
    let mut out = [0u8; 32];
    let bytes = s.as_bytes();
    let n = bytes.len().min(32);
    out[..n].copy_from_slice(&bytes[..n]);
    out
}

fn hex_decode(s: &str) -> Vec<u8> {
    (0..s.len()).step_by(2).map(|i| u8::from_str_radix(&s[i..i + 2], 16).unwrap()).collect()
}

#[test]
fn replay_golden_vectors() {
    let path = concat!(env!("CARGO_MANIFEST_DIR"), "/tests/fixtures/golden_vectors.json");
    let text = match fs::read_to_string(path) {
        Ok(t) => t,
        Err(e) => {
            panic!(
                "golden_vectors.json not found at {path} ({e}). Regenerate it with \
                 `python3 tools/staking_rewards_model.py --out core/tests/fixtures/golden_vectors.json \
                 --sequences 15 --seed 42 --min-len 8 --max-len 14` from the example's own root."
            );
        }
    };
    let root = parse_json(&text);
    let root_obj = as_obj(&root);
    let sequences = as_arr(get(root_obj, "sequences"));

    let mut total_steps = 0usize;
    let mut mismatches = Vec::new();

    for seq in sequences {
        let seq_obj = as_obj(seq);
        let steps = as_arr(get(seq_obj, "steps"));
        // Each sequence starts from a FRESH state (matches the Python
        // model's own run_golden_vectors: a new Rev3Model per sequence).
        let mut state = State::new(
            core_crate_stake_id(),
            core_crate_reward_id(),
            avm_staking_rewards_core::DEFAULT_MIN_STAKE,
            avm_staking_rewards_core::DEFAULT_FUEL_RESERVE,
        )
        .expect("DEFAULT_MIN_STAKE/DEFAULT_FUEL_RESERVE must be valid");
        for step in steps {
            total_steps += 1;
            let step_obj = as_obj(step);
            let op = as_str(get(step_obj, "op"));
            let args_obj = as_obj(get(step_obj, "args"));
            let expected_applied = as_bool(get(step_obj, "applied"));
            let expected_after_hex = as_str(get(step_obj, "state_after_hex"));

            let applied = match op {
                "stake" => {
                    let acct = account_bytes(as_str(get(args_obj, "account")));
                    let amt = as_num(get(args_obj, "amount"));
                    state.stake(acct, amt).is_ok()
                }
                "unstake" => {
                    let acct = account_bytes(as_str(get(args_obj, "account")));
                    let amt = as_num(get(args_obj, "amount"));
                    if amt == 0 {
                        false
                    } else {
                        state.unstake(acct, amt).is_ok()
                    }
                }
                "claim" => {
                    let acct = account_bytes(as_str(get(args_obj, "account")));
                    state.claim(acct).is_ok()
                }
                "fund" => {
                    let amt = as_num(get(args_obj, "amount"));
                    state.fund_rewards(amt).is_ok()
                }
                "success" => {
                    let acct = account_bytes(as_str(get(args_obj, "account")));
                    state.payout_success(acct).is_ok()
                }
                "failure" => {
                    let acct = account_bytes(as_str(get(args_obj, "account")));
                    state.payout_failure(acct).is_ok()
                }
                other => panic!("unknown op {other}"),
            };

            let after_bytes = hex_decode(expected_after_hex);
            let actual_encoded = state.encode();

            if applied != expected_applied || actual_encoded != after_bytes {
                mismatches.push(format!(
                    "seq step {total_steps}: op={op} expected_applied={expected_applied} \
                     actual_applied={applied} bytes_match={}",
                    actual_encoded == after_bytes
                ));
                if mismatches.len() > 5 {
                    break;
                }
            }
        }
        if mismatches.len() > 5 {
            break;
        }
    }

    assert!(
        mismatches.is_empty(),
        "golden vector mismatches ({} shown, {} total steps checked):\n{}",
        mismatches.len(),
        total_steps,
        mismatches.join("\n")
    );
    println!("golden vectors: {total_steps} steps replayed, 0 mismatches");
}

// The golden vectors were generated with STAKE_CURRENCY_ID=10,
// REWARD_CURRENCY_ID=11 (staking_rewards_model.py's own constants) -- these
// are not part of core's own state machine logic (core doesn't branch on
// currency id at all), only part of the header bytes being compared.
fn core_crate_stake_id() -> u32 {
    10
}
fn core_crate_reward_id() -> u32 {
    11
}
